@import "@fontsource-variable/manrope";

/* Light: warm paper, ink headings, slate body, plume teal for toggles, bars and underlines,
   mint for highlights. chart-3/4/5 double as the pastel fog behind light panels. */
:root {
  --background: oklch(0.984 0.005 91);
  --foreground: oklch(0.23 0.014 210);
  --card: oklch(0.995 0.003 91);
  --card-foreground: oklch(0.23 0.014 210);
  --popover: oklch(0.995 0.003 91);
  --popover-foreground: oklch(0.23 0.014 210);
  --primary: oklch(0.42 0.084 186);
  --primary-foreground: oklch(0.984 0.005 91);
  --secondary: oklch(0.965 0.007 90);
  --secondary-foreground: oklch(0.23 0.014 210);
  --muted: oklch(0.952 0.008 90);
  --muted-foreground: oklch(0.45 0.012 208);
  --accent: oklch(0.925 0.04 180);
  --accent-foreground: oklch(0.35 0.069 187);
  --destructive: oklch(0.58 0.2 27);
  --destructive-foreground: oklch(0.984 0.005 91);
  --border: oklch(0.9 0.008 90);
  --input: oklch(0.87 0.01 200);
  --ring: oklch(0.48 0.094 185);
  --highlight: oklch(0.9 0.055 178);
  --highlight-foreground: oklch(0.35 0.069 187);
  --glow: oklch(0.86 0.062 181);
  --chart-1: oklch(0.48 0.094 185);
  --chart-2: oklch(0.35 0.069 187);
  --chart-3: oklch(0.9 0.055 235);
  --chart-4: oklch(0.92 0.06 65);
  --chart-5: oklch(0.93 0.075 98);
  --sidebar: oklch(0.965 0.007 90);
  --sidebar-foreground: oklch(0.23 0.014 210);
  --sidebar-primary: oklch(0.42 0.084 186);
  --sidebar-primary-foreground: oklch(0.984 0.005 91);
  --sidebar-accent: oklch(0.925 0.04 180);
  --sidebar-accent-foreground: oklch(0.35 0.069 187);
  --sidebar-border: oklch(0.9 0.008 90);
  --sidebar-ring: oklch(0.48 0.094 185);

  --typeface-body: "Manrope Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Manrope Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1.25rem;
  --page-width: 72rem;
  --page-gutter: 1.5rem;
  --section-y: 8rem;
}

/* Dark: the green-black bands. Paper text, mint for hover, badges and eyebrows, teal glow
   from the fluted glass. */
.dark {
  --background: oklch(0.185 0.028 195);
  --foreground: oklch(0.984 0.005 91);
  --card: oklch(0.24 0.032 193);
  --card-foreground: oklch(0.984 0.005 91);
  --popover: oklch(0.24 0.032 193);
  --popover-foreground: oklch(0.984 0.005 91);
  --primary: oklch(0.925 0.04 180);
  --primary-foreground: oklch(0.185 0.028 195);
  --secondary: oklch(0.29 0.053 188);
  --secondary-foreground: oklch(0.984 0.005 91);
  --muted: oklch(0.26 0.035 193);
  --muted-foreground: oklch(0.78 0.016 190);
  --accent: oklch(0.3 0.04 190);
  --accent-foreground: oklch(0.984 0.005 91);
  --destructive: oklch(0.68 0.19 25);
  --destructive-foreground: oklch(0.984 0.005 91);
  --border: oklch(1 0 0 / 12%);
  --input: oklch(1 0 0 / 18%);
  --ring: oklch(0.76 0.082 182);
  --highlight: oklch(0.76 0.082 182);
  --highlight-foreground: oklch(0.24 0.032 193);
  --glow: oklch(0.5 0.09 185);
  --chart-1: oklch(0.76 0.082 182);
  --chart-2: oklch(0.48 0.094 185);
  --chart-3: oklch(0.55 0.07 235);
  --chart-4: oklch(0.6 0.08 65);
  --chart-5: oklch(0.65 0.08 98);
  --sidebar: oklch(0.21 0.03 194);
  --sidebar-foreground: oklch(0.984 0.005 91);
  --sidebar-primary: oklch(0.76 0.082 182);
  --sidebar-primary-foreground: oklch(0.185 0.028 195);
  --sidebar-accent: oklch(0.3 0.04 190);
  --sidebar-accent-foreground: oklch(0.984 0.005 91);
  --sidebar-border: oklch(1 0 0 / 12%);
  --sidebar-ring: oklch(0.76 0.082 182);
}
